package com.bank.statement.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

@Entity
@Table(name = "transactions")
public class Transaction {
    @Id @Column(name = "txn_id") private String txnId;
    @Column(name = "account_id") private String accountId;
    private String description;
    private BigDecimal amount;
    @Column(name = "txn_type") private String txnType;
    private String category;
    @Column(name = "txn_date") private LocalDate txnDate;
    private String status;

    protected Transaction() {}

    public boolean isCompleted() { return "COMPLETED".equals(status); }
    public boolean isCredit() { return "CREDIT".equals(txnType); }

    public String getTxnId() { return txnId; }
    public String getAccountId() { return accountId; }
    public String getDescription() { return description; }
    public BigDecimal getAmount() { return amount; }
    public String getTxnType() { return txnType; }
    public String getCategory() { return category; }
    public LocalDate getTxnDate() { return txnDate; }
    public String getStatus() { return status; }

    // distinct() uses equals+hashCode — match on description+amount+date
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Transaction t)) return false;
        return Objects.equals(description, t.description)
            && Objects.equals(amount, t.amount)
            && Objects.equals(txnDate, t.txnDate);
    }

    @Override
    public int hashCode() {
        return Objects.hash(description, amount, txnDate);
    }
}
