// ─── File: src/main/java/com/bank/statement/service/StatementService.java ───
package com.bank.statement.service;

import com.bank.statement.dto.StatementResponse;
import com.bank.statement.dto.StatementResponse.LineItem;
import com.bank.statement.model.*;
import com.bank.statement.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@RequiredArgsConstructor
@Slf4j
public class StatementService {

    private final AccountRepository accountRepo;

    // ═══ ALL 8 INTERMEDIATE OPS IN ONE PIPELINE ═══
    @Transactional(readOnly = true)
    public StatementResponse generateStatement(String accountId, int page, int pageSize) {
        Account account = accountRepo.findWithTransactions(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + accountId));

        List<Transaction> allTxns = account.getTransactions();

        List<LineItem> items = allTxns.stream()

            // 1. FILTER — keep completed transactions only (stateless)
            .filter(Transaction::isCompleted)

            // 2. PEEK — debug: log after filter (stateless, debug only)
            .peek(t -> log.debug("[PEEK after filter] {} {} Rs.{}",
                t.getTxnDate(), t.getDescription(), t.getAmount()))

            // 3. DISTINCT — remove duplicate entries (stateful — uses HashSet internally)
            // Uses our custom equals(description+amount+date)
            .distinct()

            // 4. SORTED — by date descending (stateful — buffers ALL elements)
            .sorted(Comparator.comparing(Transaction::getTxnDate).reversed()
                .thenComparing(Transaction::getAmount).reversed())

            // 5. SKIP — pagination: skip previous pages (stateful — counter)
            .skip((long) page * pageSize)

            // 6. LIMIT — take only pageSize elements (stateful — short-circuit counter)
            .limit(pageSize)

            // 7. MAP — transform Transaction entity → LineItem DTO (stateless)
            .map(t -> new LineItem(
                t.getTxnDate().toString(),
                t.getDescription(),
                t.getTxnType(),
                t.getAmount(),
                t.getCategory()))

            // TERMINAL — collect results
            .toList();

        // Separate pipelines for totals (across ALL completed, not just this page)
        BigDecimal totalCredits = allTxns.stream()
            .filter(Transaction::isCompleted)
            .filter(Transaction::isCredit)
            .map(Transaction::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        BigDecimal totalDebits = allTxns.stream()
            .filter(Transaction::isCompleted)
            .filter(t -> !t.isCredit())
            .map(Transaction::getAmount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        long uniqueCompleted = allTxns.stream()
            .filter(Transaction::isCompleted)
            .distinct()
            .count();

        return new StatementResponse(accountId, account.getHolderName(),
            page, pageSize, (int) uniqueCompleted, totalCredits, totalDebits, items,
            "filter(completed) → peek(debug) → distinct(dedup) → sorted(date desc) → skip(page) → limit(size) → map(toDTO)");
    }

    // ═══ FLATMAP DEMO — flatten nested accounts→transactions ═══
    @Transactional(readOnly = true)
    public List<LineItem> allTransactionsAcrossAccounts() {
        List<Account> accounts = accountRepo.findAllWithTransactions();

        // WITHOUT flatMap: Stream<List<Transaction>> — NESTED!
        // WITH flatMap: Stream<Transaction> — FLAT!
        return accounts.stream()
            .flatMap(account -> account.getTransactions().stream())  // FLATMAP: Account → Stream<Transaction>
            .filter(Transaction::isCompleted)
            .distinct()
            .sorted(Comparator.comparing(Transaction::getTxnDate).reversed())
            .map(t -> new LineItem(t.getTxnDate().toString(), t.getDescription(),
                t.getTxnType(), t.getAmount(), t.getCategory()))
            .toList();
    }
}
