// ─── File: src/test/java/com/bank/statement/service/IntermediateOpsTest.java ───
package com.bank.statement.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class IntermediateOpsTest {

    // ═══ FILTER: keep matching elements ═══
    @Test
    void filterKeepsMatching() {
        List<Integer> scores = List.of(780, 580, 650, 490, 750);
        List<Integer> eligible = scores.stream()
            .filter(s -> s >= 650)
            .toList();
        assertThat(eligible).containsExactly(780, 650, 750);
    }

    // ═══ MAP: transform each element ═══
    @Test
    void mapTransformsType() {
        List<String> symbols = List.of("reliance", "tcs");
        List<String> upper = symbols.stream()
            .map(String::toUpperCase)
            .toList();
        assertThat(upper).containsExactly("RELIANCE", "TCS");
    }

    // ═══ FLATMAP: one-to-many + flatten ═══
    @Test
    void flatMapFlattensNestedStructure() {
        List<List<String>> nested = List.of(
            List.of("RELIANCE", "TCS"),
            List.of("HDFC", "INFY"),
            List.of("WIPRO")
        );
        List<String> flat = nested.stream()
            .flatMap(Collection::stream)   // List<List<String>> → Stream<String>
            .toList();
        assertThat(flat).containsExactly("RELIANCE", "TCS", "HDFC", "INFY", "WIPRO");
    }

    // ═══ SORTED: stateful — buffers all ═══
    @Test
    void sortedBuffersAllElements() {
        List<String> log = new ArrayList<>();

        List.of("C", "A", "B").stream()
            .peek(s -> log.add("before-sort:" + s))
            .sorted()
            .peek(s -> log.add("after-sort:" + s))
            .toList();

        // ALL elements pulled before sort emits any
        assertThat(log.subList(0, 3)).containsExactly(
            "before-sort:C", "before-sort:A", "before-sort:B");
        // Then emitted in sorted order
        assertThat(log.subList(3, 6)).containsExactly(
            "after-sort:A", "after-sort:B", "after-sort:C");
    }

    // ═══ DISTINCT: removes duplicates by equals+hashCode ═══
    @Test
    void distinctRemovesDuplicates() {
        List<String> unique = Stream.of("RELIANCE", "TCS", "RELIANCE", "HDFC", "TCS")
            .distinct()
            .toList();
        assertThat(unique).containsExactly("RELIANCE", "TCS", "HDFC"); // first-occurrence order
    }

    // ═══ LIMIT + SKIP: pagination ═══
    @Test
    void skipAndLimitPaginate() {
        List<String> allItems = List.of("A", "B", "C", "D", "E", "F", "G");

        List<String> page0 = allItems.stream().skip(0).limit(3).toList();
        List<String> page1 = allItems.stream().skip(3).limit(3).toList();
        List<String> page2 = allItems.stream().skip(6).limit(3).toList();

        assertThat(page0).containsExactly("A", "B", "C");
        assertThat(page1).containsExactly("D", "E", "F");
        assertThat(page2).containsExactly("G");
    }

    // ═══ PEEK: debug only, does not modify ═══
    @Test
    void peekDoesNotModifyStream() {
        List<String> peeked = new ArrayList<>();

        List<String> result = Stream.of("RELIANCE", "TCS")
            .peek(peeked::add)
            .map(String::toLowerCase)
            .toList();

        assertThat(result).containsExactly("reliance", "tcs");
        assertThat(peeked).containsExactly("RELIANCE", "TCS"); // original values, not lowered
    }

    // ═══ ALL INTERMEDIATE OPS ARE LAZY ═══
    @Test
    void allIntermediateOpsAreLazy() {
        AtomicInteger count = new AtomicInteger(0);

        Stream<String> pipeline = Stream.of("A", "B", "C")
            .filter(s -> { count.incrementAndGet(); return true; })
            .map(s -> { count.incrementAndGet(); return s; })
            .sorted()
            .distinct();

        assertThat(count.get()).isZero(); // NOTHING executed yet!

        pipeline.toList(); // terminal triggers all
        assertThat(count.get()).isGreaterThan(0);
    }
}
